<?php namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use Illuminate\Http\Request;abstract class CrudController extends Controller{protected string $model;protected array $rules=[];protected array $with=[];public function index(Request $r){$q=($this->model)::query()->with($this->with);if($r->filled('search')){$s=$r->string('search');$q->where(function($x)use($s){foreach(($this->searchable??[]) as $i=>$col){$i?$x->orWhere($col,'ilike',"%$s%"): $x->where($col,'ilike',"%$s%");}});}return $q->latest()->paginate(min((int)$r->get('per_page',50),300));}public function store(Request $r){return response()->json(($this->model)::create($r->validate($this->rules))->load($this->with),201);}public function show(int $id){return ($this->model)::with($this->with)->findOrFail($id);}public function update(Request $r,int $id){$m=($this->model)::findOrFail($id);$m->update($r->validate($this->rules));return $m->fresh($this->with);}public function destroy(int $id){($this->model)::findOrFail($id)->delete();return response()->noContent();}}
